TLM.f("Commune/C3",{"officium":"Commune Plurimorum Martyrum extra tempus paschale: Intret in conspectu","rule":[],"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Beatórum Mártyrum paritérque Pontíficum N. et N. nos, quǽsumus, Dómine, festa tueántur: et eórum comméndet orátio veneránda."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 3:1-8"},{"k":"text","la":"Justorum ánimæ in manu Dei sunt, et non tanget illos torméntum mortis. Visi sunt oculis insipiéntium mori: et æstimála est afflíctio exitus illórum: et quod a nobis est iter, extermínium: illi autem sunt in pace. Et si coram homínibus torménta passi sunt, spes illórum immortalitáte plena est. In paucis vexáti, in multis bene disponéntur: quóniam Deus tentávit eos, et invenit illos dignos se. Tamquam aurum in fornáce probávit illos, et quasi holocáusti hóstiam accépit illos, et in témpore erit respéctus illorum. Fulgébunt justi, et tamquam scintíllæ in arundinéto discúrrent. Judicábunt natiónes, et dominabúntur pópulis, et regnábit Dóminus illórum in perpétuum."}],"Graduale":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Eccl 44:14"},{"k":"text","la":"Córpora Sanctórum in pace sepúlta sunt, et nómina eórum vivent in generatiónem et generatiónem. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 21:9-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum audiéritis prǽlia et seditiónes, nolíte terréri: opórtet primum hæc fíeri, sed nondum statim finis. Tunc dicébat illis: Surget gens contra gentem, et regnum advérsus regnum. Et terræmótus magni erunt per loca, et pestiléntiæ, et fames, terrorésque de coelo, et signa magna erunt. Sed ante hæc ómnia injícient vobis manus suas, et persequéntur tradéntes in synagógas et custódias, trahéntes ad reges et praesides propter nomen meum: contínget autem vobis in testimónium. Pónite ergo in córdibus vestris non præmeditári, quemádmodum respondeátis. Ego enim dabo vobis os et sapiéntiam, cui non potérunt resístere et contradícere omnes adversárii vestri. Tradémini autem a paréntibus, et frátribus, et cognátis, et amícis, et morte affícient ex vobis: et éritis ódio ómnibus propter nomen meum: et capíllus de cápite vestro non períbit. In patiéntia vestra possidébitis ánimas vestras."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Adésto, Dómine, supplicatiónibus nostris, quas in Sanctórum tuórum commemoratióne deférimus: ut, qui nostræ justítiæ fidúciam non habémus, eórum, qui tibi placuérunt, méritis adjuvémur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:4-6"},{"k":"text","la":"Et si coram homínibus torménta passi sunt, Deus tentávit eos: tamquam aurum in fornáce probávit eos, et quasi holocáusta accépit eos."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, salutáribus repléti mystériis: ut, quorum sollémnia celebrámus, eórum oratiónibus adjuvémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fb339773d9c17ccf":{"t":"Ps 78, 11 i 12 i 10, Ps 78, 1\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih! (Ps 78, 1) Bože, narodi prodiru u nasljedstvo tvoje, skvrne sveti hram tvoj, pretvaraju Jeruzalem u razvaline.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih!"},"31b01e9da7f36b37":null,"12377bf15a3430a7":{"t":"Mudr 3, 1-8\nČitanje knjige Mudrosti. Duše su pravednika u Božjoj ruci i neće ih dotaknuti smrtna muka. U očima nerazumnih izgledalo je kao da su mrtvi. Njihovu smrt smatrali su kao nesreću i njihov rastanak kao propast. Ali oni su u pokoju. I ako su pred ljudima trpjeli muke, njihova je nada puna besmrtnosti. Za kratko trpljenje bit će obilno nagrađeni, jer ih je Bog iskušao i našao ih dostojnima sebe. Iskušao ih je kao zlato u peći i primio ih je kao žrtvu paljenicu i nagradit će ih u svoje vrijeme. Pravednici će sjati i blistati kao iskre na trstici, sudit će narodima i upravljat će plemenima, a njihov će Gospodin vladati na vijeke."},"31f7cef74606cebe":{"t":"Izl 15, 11, Izl 15, 6\n(Izl 15, 11) Slavan je Bog u svojim svetima, divan u veličanstvu, čini čudesa. (Izl 15, 6) Snagom se proslavila desnica tvoja, Gospodine, desnica je tvoja uništila neprijatelje.\n\nSir 44, 14\n<i>Aleluja</i>, <i>aleluja</i>.\nTjelesa su svetih u miru sahranjena, a njihova imena žive od koljena do koljena. <i>Aleluja</i>."},"ff852e407899a76c":{"t":"Lk 21, 9-19\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Kad čujete da se govori o ratovima i bunama, nemojte se plašiti, jer treba da to bude prije, ali još nije odmah svršetak. Tada im reče: Ustat će narod na narod i kraljevstvo na kraljevstvo i na različitim će mjestima biti veliki potresi i kuge i glad i strahote, a na nebu veliki znaci. Ali prije svega toga stavit će na vas ruke i progoniti, predavat će vas u sinagoge i bacati u tamnice, radi mene povlačit će vas pred kraljeve i upravitelje. I to će vam se dogoditi da vi posvjedočite. Zato budite mirni i ne smišljajte unaprijed kako ćete odgovarati, jer ću vam ja dati riječ i mudrost kojoj se neće moći oprijeti ni usprotiviti nitko od svih vaših protivnika. Bit ćete izdani od roditelja i braće i rođaka i prijatelja, a neke će od vas usmrtiti. Svi će vas mrziti radi mene, ali neće propasti ni vlas s vaše glave. Svojom strpljivošću spasit ćete svoj život."},"dd478a333f4e9a0c":{"t":"Ps 67, 36\nDivan je Bog u svojim svetima. Bog Izraelov daje krepost i snagu puku svojemu. Blagoslovljen Bog. <i>Aleluja</i>."},"199a4c797ae93af1":{"t":"Usliši, Gospodine, naše ponizne molitve koje ti prinosimo o spomenu tvojih svetih da nas koji se ne uzdamo u svoju pravednost pomognu zasluge onih koji su ti se svidjeli.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"818b40676ad77c2d":{"t":"Mudr 3, 4 i 5 i 6\nI ako su pred ljudima trpjeli muke, Bog ih je iskušao. Prokušao ih je kao zlato u peći i primio ih je kao žrtve paljenice."},"8f97cddf4173d144":{"t":"<i>Pomolimo se</i>.\nNasićeni spasonosnim tajnama, molimo, Gospodine, da nas pomažu molitve onih kojih svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
